use rand::Rng;

fn shift(key: &str, s: &str, decode: bool) -> Option<String> {
    if key.is_empty() || !key.chars().all(|c| c.is_ascii_lowercase()) {
        return None;
    }
    let shifts: Vec<u8> = key.bytes().map(|b| b - b'a').collect();
    let mut result = String::with_capacity(s.len());
    for (i, c) in s.chars().enumerate() {
        if !c.is_ascii_lowercase() {
            return None;
        }
        let k = shifts[i % shifts.len()] as i32;
        let base = (c as u8 - b'a') as i32;
        let shifted = if decode { base - k } else { base + k };
        result.push((b'a' + shifted.rem_euclid(26) as u8) as char);
    }
    Some(result)
}

pub fn encode(key: &str, s: &str) -> Option<String> {
    shift(key, s, false)
}

pub fn decode(key: &str, s: &str) -> Option<String> {
    shift(key, s, true)
}

pub fn encode_random(s: &str) -> (String, String) {
    let mut rng = rand::thread_rng();
    let len = 100 + rng.gen_range(0..100);
    let key: String = (0..len)
        .map(|_| (b'a' + rng.gen_range(0..26)) as char)
        .collect();
    let encoded = encode(&key, s).expect("generated key is valid");
    (key, encoded)
}

